(function(){
  "use strict";
  var ASSET_BASE=(typeof window!=="undefined" && window.FIET_ASSETS) ? window.FIET_ASSETS : "";   // "" en estático; URL del tema en WordPress
  var TWO_PI=Math.PI*2, DEG=Math.PI/180;
  var reduce=window.matchMedia("(prefers-reduced-motion:reduce)").matches;
  var canvas=document.getElementById("c");
  if(!canvas) return;                 // en páginas sin lienzo (portada El teléfono) main.js no hace nada
  var ctx=canvas.getContext("2d");
  var introEl=document.getElementById("intro");
  var prevRecoEl=document.getElementById("prevReco");   // bloque "Recomendaciones + cards" (portada Prevención)
  var quizEl=document.getElementById("quiz");
  var paraEl=document.getElementById("para"), hintEl=document.getElementById("hint"), eyebrow=document.getElementById("eyebrow");
  var para2El=document.getElementById("para2"), eyebrow2El=document.getElementById("eyebrow2"), copy2bodyEl=document.getElementById("copy2body");
  var copy2bEl=document.getElementById("copy2b");           // relevo: 2ª aparición de "La trata en España"
  var para4El=document.getElementById("para4");             // texto grande (estilo ¿qué es la trata?) del relevo
  var eltitleEl=document.getElementById("eltitle"), elemsEl=document.getElementById("elements"), eyebrow3El=document.getElementById("eyebrow3");
  var copy2El=document.getElementById("copy2");
  var carasEl=document.getElementById("caras");
  var orbCoverEl=document.getElementById("orbCover");
  var elCards=document.querySelectorAll(".el-card");
  var track=document.querySelector(".hero-track");
  var COVER=!!(track && track.hasAttribute("data-cover"));   // modo "solo portada": persona -> mapamundi + texto
  var STATIC=!!(track && track.hasAttribute("data-static")); // muestra el fotograma del vídeo 1 fijo (sin scroll ni fragmentación)
  function shuffle(a){for(var i=a.length-1;i>0;i--){var j=(Math.random()*(i+1))|0,t=a[i];a[i]=a[j];a[j]=t;}return a;}
  function clamp(v,a,b){return v<a?a:v>b?b:v;}
  function remap(v,a,b){return clamp((v-a)/(b-a),0,1);}
  function easeInOut(t){return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}
  function lerp(a,b,t){return a+(b-a)*t;}

  var raw=paraEl.textContent; paraEl.textContent=""; var chars=[];
  for(var i=0;i<raw.length;i++){var s=document.createElement("span");s.className="ch";s.textContent=raw[i];paraEl.appendChild(s);chars.push(s);}
  var chars3=[];
  if(eltitleEl){ var raw3=eltitleEl.textContent; eltitleEl.textContent=""; for(var i=0;i<raw3.length;i++){var s3=document.createElement("span");s3.className="ch";s3.textContent=raw3[i];eltitleEl.appendChild(s3);chars3.push(s3);} }
  var chars2=[];
  if(para2El){ var raw2=para2El.textContent; para2El.textContent=""; for(var i=0;i<raw2.length;i++){ if(raw2[i]==="|"){ para2El.appendChild(document.createElement("br")); continue; } var s2=document.createElement("span");s2.className="ch";s2.textContent=raw2[i];para2El.appendChild(s2);chars2.push(s2);} }
  var chars4=[];
  if(para4El){ var raw4=para4El.textContent; para4El.textContent=""; for(var i=0;i<raw4.length;i++){var s4=document.createElement("span");s4.className="ch";s4.textContent=raw4[i];para4El.appendChild(s4);chars4.push(s4);} }

  var LON_MIN=-180, LON_STEP=1.25, NLON=288, LAT_MAX=84, LAT_STEP=1.25, NLAT=135;
  var LANDMASK="";
  var globe=[];
  for(var r=0;r<NLAT;r++){ var lat=LAT_MAX-r*LAT_STEP;
    for(var col=0;col<NLON;col++){
      if(LANDMASK.charCodeAt(r*NLON+col)===48) continue;
      var lon=LON_MIN+col*LON_STEP, la=lat*DEG, lo=lon*DEG;
      globe.push({x:Math.cos(la)*Math.sin(lo), y:Math.sin(la), z:Math.cos(la)*Math.cos(lo)});
    } }
  shuffle(globe);

  // Marcadores tipo "mapa de estadísticas": puntos amarillos que laten (escala) en varios países.
  var MARKERS=[];
  (function(){
    // [lat, lon, factor de tamaño opcional]
    var pts=[[40.4,-3.7],[9,8,1.9],[21,78],[-10,-52,1.9],[23,-102],[15,100],[45,25],[39,-98],[1,38],[12,122],[4,-73,1.9]];
    for(var mi=0;mi<pts.length;mi++){
      var mla=pts[mi][0]*DEG, mlo=pts[mi][1]*DEG, big=pts[mi][2]||1;
      MARKERS.push({ x:Math.cos(mla)*Math.sin(mlo), y:Math.sin(mla), z:Math.cos(mla)*Math.cos(mlo),
        phase:Math.random()*TWO_PI, speed:1.5+Math.random()*1.3, size:(0.019+Math.random()*0.011)*big });
    }
  })();

  var SPAIN_MARKERS=[[-0.1413,0.1293,0.028],[-0.0899,-0.1613,0.028],[0.2860,-0.2678,0.020],[-0.3738,-0.3688,0.020],[0.1397,-0.0515,0.020],[-0.0070,-0.3838,0.017],[-0.0456,-0.0840,0.018],[0.1206,-0.2399,0.018]].map(function(m){return {u:m[0],v:m[1],size:m[2],phase:Math.random()*TWO_PI,speed:1.5+Math.random()*1.3};});
  var COLS=8, ROWS=6, FRAMES=48, FW=640, FH=540;
  var sprite=new Image(), spriteReady=false, cellsReady=false, cells=[], P=[], N=0;
  // Vídeo 2 (lo que reconstruyen los fragmentos). PLACEHOLDER: el mismo sprite actual.
  // Para el clip definitivo: pon V2.src con su sprite-sheet y ajusta cols/rows/frames/fw/fh/frame.
  var V2={ src:ASSET_BASE+"video2.webp", cols:6, rows:5, frames:26, fw:720, fh:720, frame:0 };
  var sprite2=new Image(), sprite2Ready=false, cells2=[];
  var GW=140, GH=118;
  sprite.onload=function(){ spriteReady=true; if(!sprite2.src){ sprite2.src=V2.src||sprite.src; } tryBuild(); };
  sprite2.onload=function(){ sprite2Ready=true; tryBuild(); };
  var SPAIN={ src:ASSET_BASE+"spain.png", fw:760, fh:736 };
  var spainImg=new Image(), spainReady=false, spainCells=[];
  spainImg.onload=function(){ spainReady=true; tryBuild(); };
  spainImg.src=SPAIN.src;
  var COMP={ src:ASSET_BASE+"comp.webp", fw:1408, fh:410, strips:[[0,0.1953],[0.1953,0.2692],[0.2692,0.3693],[0.3693,0.468],[0.468,0.5653],[0.5653,0.6378],[0.6378,0.7599],[0.7599,0.8473],[0.8473,1]] };
  var compImg=new Image(), compReady=false, compCells=[], compBlur=null;
  var revealed=[false,false,false,false,false,false,false,false,false];
  var revealAmt=[0,0,0,0,0,0,0,0,0];
  compImg.onload=function(){ compReady=true;
    compBlur=document.createElement("canvas"); compBlur.width=COMP.fw; compBlur.height=COMP.fh;
    var bctx=compBlur.getContext("2d"); bctx.filter="blur(9px)"; bctx.drawImage(compImg,0,0); bctx.filter="none";
    tryBuild(); };
  compImg.src=COMP.src;
  var caraCards=document.querySelectorAll(".cara-card");   // hover en card -> revela a la persona
  for(var ci=0;ci<caraCards.length;ci++){ (function(idx){ caraCards[idx].addEventListener("mouseenter",function(){ revealed[idx]=true; }); })(ci); }
  sprite.src=ASSET_BASE+"video1.jpg";

  function sampleFrame(img, frameIdx, cols, fw, fh){
    var off=document.createElement("canvas"); off.width=GW; off.height=GH;
    var o=off.getContext("2d");
    var col=frameIdx%cols, row=(frameIdx/cols)|0;
    o.drawImage(img, col*fw,row*fh,fw,fh, 0,0,GW,GH);
    var d=o.getImageData(0,0,GW,GH).data, arr=[];
    for(var y=0;y<GH;y++){ for(var x=0;x<GW;x++){
      var k=(y*GW+x)*4, rr=d[k],gg=d[k+1],bb=d[k+2];
      if((255-rr)+(255-gg)+(255-bb) < 60) continue;
      arr.push({ u:x/GW-0.5, v:y/GH-0.5, r:rr, g:gg, b:bb });
    } }
    shuffle(arr);
    return arr;
  }

  function tryBuild(){
    if(!spriteReady || !sprite2Ready || !spainReady || !compReady || !globe.length) return;
    cells  = sampleFrame(sprite,  FRAMES-1, COLS,    FW,    FH);     // vídeo 1 (origen): último fotograma
    cells2 = sampleFrame(sprite2, V2.frame, V2.cols, V2.fw, V2.fh);  // vídeo 2 (destino): fotograma elegido
    spainCells = sampleFrame(spainImg, 0, 1, SPAIN.fw, SPAIN.fh);  // mapa de España (paso intermedio)
    compCells = sampleFrame(compImg, 0, 1, COMP.fw, COMP.fh);     // 9 caras (paso intermedio)
    N=Math.min(globe.length, cells.length, cells2.length);
    P=new Array(N);
    for(var i=0;i<N;i++){
      var c=cells[i];
      var proj=c.u*0.96 + c.v*0.28;
      var posDelay=clamp((0.62-proj)/1.24,0,1);
      var delay=clamp(0.7*posDelay + 0.3*Math.random(),0,1)*0.6;
      P[i]={ cell:c, glb:globe[i], cell2:cells2[i], spain:spainCells[i % spainCells.length], comp:compCells[i % compCells.length],
        delay:delay,
        wind:0.45+Math.random()*1.15,
        lat:(Math.random()*2-1),
        swayA:0.5+Math.random()*1.1,
        swayF:1.0+Math.random()*2.2,
        phase:Math.random()*TWO_PI,
        bob:Math.random() };
    }
    cellsReady=true;
    if(COVER) buildLighthouse();           // asigna a cada partícula su píxel del faro
  }

  var W=0,H=0,dpr=1,cx=0,cy=0,R=0,imgCx=0,imgCy=0,imgW=0,imgH=0,imgPitch=0,img2Cx=0,img2Cy=0,img2W=0,img2H=0,img2Pitch=0,spainCx=0,spainCy=0,spnW=0,spnH=0,spainPitch=0,compCx=0,compCy=0,compW=0,compH=0,compPitch=0;
  function resize(){
    dpr=Math.min(window.devicePixelRatio||1,2);
    W=canvas.clientWidth; H=canvas.clientHeight;
    canvas.width=W*dpr; canvas.height=H*dpr; ctx.setTransform(dpr,0,0,dpr,0,0);
    var mobile=W<760;
    cx=mobile?W*0.5:W*0.70; cy=mobile?H*0.42:H*0.5;
    R=Math.min(W,H)*(mobile?0.30:0.33);
    spainCx=cx; spainCy=cy; spnH=R*2.0; spnW=spnH*(SPAIN.fw/SPAIN.fh); spainPitch=spnW/GW; // mapa de España donde estaba el globo
    compW=Math.min(W*0.96,1900); compH=compW*(COMP.fh/COMP.fw); compCx=W*0.5; compCy=H-compH*0.5-H*0.03; compPitch=compW/GW; // 9 caras centradas
    // colocación del vídeo 2 reconstruido (móvil: a sangre completa; desktop: columna izquierda)
    img2W=mobile?(W*1.25):(H*(V2.fw/V2.fh));      // móvil: sangra por los lados (sin espacio lateral)
    img2H=mobile?(img2W*(V2.fh/V2.fw)):H;
    img2Cx=mobile?W*0.5:W*0.30;
    img2Cy=mobile?(img2H*0.5):H*0.5;              // móvil: pegado arriba (sin espacio superior)
    img2Pitch=img2W/GW;
    imgH=mobile?(W*(FH/FW)):H;              // móvil: ancho completo; desktop: alto completo
    imgW=imgH*(FW/FH);
    imgCx=mobile?(W*0.5):(W - imgW*0.4375); // móvil: centrada a sangre; desktop: pegada a la derecha
    imgCy=imgH*0.5;
    imgPitch=imgW/GW;
    if(COVER) buildLighthouse();           // portada Prevención: destino = silueta de un faro (se forma como el mapamundi)
  }

  // ---- Portada (Prevención): las partículas forman la silueta de un faro ----
  var lhPts=[];
  function buildLighthouse(){
    if(!COVER || !R) return;
    var LW=Math.round(R*1.15), LH=Math.round(R*2.25), c0=LW/2;
    var off=document.createElement("canvas"); off.width=LW; off.height=LH;
    var o=off.getContext("2d"); o.fillStyle="#000";
    o.fillRect(c0-0.30*LW, 0.90*LH, 0.60*LW, 0.10*LH);                       // base
    o.beginPath();                                                          // torre (tronco-cónica)
    o.moveTo(c0-0.24*LW, 0.90*LH); o.lineTo(c0-0.12*LW, 0.245*LH);
    o.lineTo(c0+0.12*LW, 0.245*LH); o.lineTo(c0+0.24*LW, 0.90*LH);
    o.closePath(); o.fill();
    o.fillRect(c0-0.20*LW, 0.195*LH, 0.40*LW, 0.052*LH);                     // galería
    o.fillRect(c0-0.115*LW, 0.085*LH, 0.23*LW, 0.112*LH);                    // linterna
    o.beginPath();                                                          // cúpula
    o.moveTo(c0-0.15*LW, 0.09*LH); o.lineTo(c0, 0); o.lineTo(c0+0.15*LW, 0.09*LH);
    o.closePath(); o.fill();
    var d; try{ d=o.getImageData(0,0,LW,LH).data; }catch(e){ return; }
    lhPts=[]; var step=4;
    for(var y=0;y<LH;y+=step){ for(var x=0;x<LW;x+=step){ if(d[(y*LW+x)*4+3]>128) lhPts.push({dx:x-LW/2, dy:y-LH/2}); } }
    assignLighthouse();
  }
  function assignLighthouse(){
    if(!COVER || !P || !P.length || !lhPts.length) return;
    for(var i=0;i<P.length;i++){ P[i].lh=lhPts[i%lhPts.length]; }
  }
  window.addEventListener("resize",resize); resize();

  function drawComp(alpha){
    if(!compReady||alpha<=0) return;
    var dx=compCx-compW/2, dy=compCy-compH/2;
    ctx.globalAlpha=alpha; ctx.drawImage(compBlur,0,0,COMP.fw,COMP.fh, dx,dy,compW,compH);   // todas borrosas
    for(var i=0;i<9;i++){
      if(revealAmt[i]<=0.01) continue;
      var s0=COMP.strips[i][0]*COMP.fw, sw=(COMP.strips[i][1]-COMP.strips[i][0])*COMP.fw;
      var d0=dx+COMP.strips[i][0]*compW, dw=(COMP.strips[i][1]-COMP.strips[i][0])*compW;
      ctx.globalAlpha=alpha*revealAmt[i]; ctx.drawImage(compImg, s0,0,sw,COMP.fh, d0,dy,dw,compH); // nitida al hacer hover
    }
    ctx.globalAlpha=1;
  }
  var p=0;
  // La animación termina al 80% del track; el último 20% queda en estado final (estático)
  // mientras la sección del formulario sube por encima (efecto cover).
  function onScroll(){ if(STATIC){ p=0; return; } var rect=track.getBoundingClientRect();var total=track.offsetHeight-window.innerHeight;var raw=-rect.top/total;p=COVER?clamp(raw*0.40,0,1):clamp(raw/0.80,0,1);}
  window.addEventListener("scroll",onScroll,{passive:true}); onScroll();

  var TURNS=1.6;
  function frame(){
    var pp=STATIC?0:(reduce?1:p);
    // ---- línea de tiempo ----
    var m1=remap(pp,0.07,0.17);                 // persona -> mapamundi (tras terminar el giro)
    var angle1=TWO_PI*(TURNS*easeInOut(remap(pp,0.10,0.36)) + 0.8*pp);
    var reveal=remap(pp,0.19,0.28);             // texto 1 (junto al mapamundi, tras formarse el globo)
    var mS=remap(pp,0.37,0.48);                 // mapamundi -> mapa de Espana
    var reveal2=remap(pp,0.48,0.55);            // texto 2 (titulo, junto a Espana)
    var reveal3=remap(pp,0.75,0.78);            // titulo "tres elementos"
    var reveal4=remap(pp,0.62,0.665);           // 2º texto de España: revelado SOLO después de aparecer el texto completo
    // Orbe Madrid: crece (0.68-0.74), se mantiene lleno mientras se leen los "tres elementos",
    // y SOLO se contrae (0.82-0.855) una vez que el texto ya se ha retirado (out 0.80-0.82).
    var grow=remap(pp,0.68,0.74), shrink=remap(pp,0.82,0.855), coverT=grow*(1-shrink);
    var CARAS=false;                            // TEMP: oculta la seccion "9 caras". Poner true para recuperarla.
    var mComp=remap(pp,0.78,0.84);              // Espana -> 9 caras
    var m2=CARAS?remap(pp,0.91,0.96):remap(pp,0.86,0.93);   // caras/Espana -> video 2
    var esFrag=CARAS?0.78:0.86;                 // p en que Espana empieza a fragmentarse
    var spainPhase = pp>=0.37 && pp<esFrag;
    var compPhase = CARAS && pp>=0.78 && pp<0.91;
    var v2Phase = pp>=(CARAS?0.91:0.86);

    // ---- textos ----
    var lit=Math.floor(reveal*chars.length);
    for(var i=0;i<chars.length;i++){var on=i<lit; if(on!==chars[i]._on){chars[i]._on=on;chars[i].classList.toggle("lit",on);}}
    if(chars2.length){ var lit2=Math.floor(reveal2*chars2.length);
      for(var j=0;j<chars2.length;j++){var on2=j<lit2; if(on2!==chars2[j]._on){chars2[j]._on=on2;chars2[j].classList.toggle("lit",on2);}} }
    eyebrow.classList.toggle("show", pp>0.17 && pp<0.35);
    if(eyebrow2El) eyebrow2El.classList.toggle("show", pp>0.46 && pp<(esFrag+0.04));
    if(hintEl) hintEl.style.opacity = pp>0.04?0:1;
    paraEl.style.opacity = remap(pp,0.17,0.21) * (1 - remap(pp,0.34,0.37));
    if(para2El) para2El.style.opacity = remap(pp,0.46,0.50);
    if(copy2bodyEl) copy2bodyEl.style.opacity = remap(pp,0.505,0.55);
    // El bloque original (rótulo + título + párrafo) da paso al 2º texto: se retira ~0.55-0.585
    if(copy2El) copy2El.style.opacity = (1 - remap(pp,0.55,0.585));
    // Relevo: 2ª aparición (mismo estilo que "¿qué es la trata?"). Primero aparece el texto completo
    // (0.585-0.61) y SOLO DESPUÉS se revelan las palabras (reveal4, 0.62-0.665).
    if(chars4.length){ var lit4=Math.floor(reveal4*chars4.length);
      for(var k=0;k<chars4.length;k++){var on4=k<lit4; if(on4!==chars4[k]._on){chars4[k]._on=on4;chars4[k].classList.toggle("lit",on4);}} }
    // El texto persiste: el círculo amarillo (z-index superior) lo tapa al expandirse y lo vuelve a
    // descubrir al contraerse. Solo se retira cuando el mapa de España se transforma en vídeo (0.86-0.90).
    if(copy2bEl) copy2bEl.style.opacity = remap(pp,0.585,0.61) * (1 - remap(pp,0.86,0.90));
    if(introEl) introEl.style.opacity = 1 - remap(pp,0.05,0.13);
    var lit3=chars3.length?Math.floor(reveal3*chars3.length):0;                       // titulo "tres elementos"
    for(var e=0;e<chars3.length;e++){var on3=e<lit3; if(on3!==chars3[e]._on){chars3[e]._on=on3;chars3[e].classList.toggle("lit",on3);}}
    if(elemsEl) elemsEl.style.opacity = remap(pp,0.75,0.78) * (1 - remap(pp,0.80,0.82));
    if(eyebrow3El) eyebrow3El.classList.toggle("show", pp>0.75 && pp<0.82);
    for(var cc=0;cc<elCards.length;cc++){ elCards[cc].classList.toggle("show", pp > (0.76+cc*0.015)); }
    if(quizEl){ var qo=remap(pp,0.96,0.995); quizEl.style.opacity=qo; quizEl.style.pointerEvents=qo>0.5?"auto":"none"; }
    for(var rv=0;rv<9;rv++){ revealAmt[rv]+=((revealed[rv]?1:0)-revealAmt[rv])*0.14; }   // suaviza el enfoque por hover
    if(carasEl){ var cav=CARAS?remap(pp,0.81,0.84)*(1-remap(pp,0.90,0.93)):0; carasEl.style.opacity=cav; carasEl.style.pointerEvents=cav>0.5?"auto":"none"; }

    ctx.clearRect(0,0,W,H);

    // ---- persona (fotogramas) ----
    if(spriteReady && pp<0.11){
      var fa=1-remap(pp,0.07,0.11);
      if(fa>0){
        var fi=clamp(Math.round(remap(pp,0,0.07)*(FRAMES-1)),0,FRAMES-1);
        var fcol=fi%COLS, frow=(fi/COLS)|0;
        ctx.globalAlpha=fa;
        ctx.drawImage(sprite, fcol*FW,frow*FH,FW,FH, imgCx-imgW/2,imgCy-imgH/2,imgW,imgH);
        ctx.globalAlpha=1;
        var ix0=imgCx-imgW/2, yb=imgCy+imgH/2;
        var bandB=imgH*0.18, bandL=imgW*0.42, bandX=W*0.12;
        ctx.globalCompositeOperation="destination-out";
        var gB=ctx.createLinearGradient(0,yb-bandB,0,yb);
        gB.addColorStop(0,"rgba(0,0,0,0)"); gB.addColorStop(1,"rgba(0,0,0,1)");
        ctx.fillStyle=gB; ctx.fillRect(0,yb-bandB,W,bandB);
        var gL=ctx.createLinearGradient(ix0,0,ix0+bandL,0);
        gL.addColorStop(0,"rgba(0,0,0,1)"); gL.addColorStop(1,"rgba(0,0,0,0)");
        ctx.fillStyle=gL; ctx.fillRect(ix0,0,bandL,H);
        var gR=ctx.createLinearGradient(W-bandX,0,W,0);
        gR.addColorStop(0,"rgba(0,0,0,0)"); gR.addColorStop(1,"rgba(0,0,0,1)");
        ctx.fillStyle=gR; ctx.fillRect(W-bandX,0,bandX,H);
        ctx.globalCompositeOperation="source-over";
      }
    }

    // ---- ESCENA 1: persona -> mapamundi ----
    if(cellsReady && pp>=0.07 && (COVER || pp<0.37)){
      var sin=Math.sin(angle1),cos=Math.cos(angle1);
      var wdx=-0.95, wdy=-0.30, pxx=0.30, pyy=-0.95;
      var WIND=R*1.35, LAT=R*0.75, SWAY=R*0.30, BOB=R*0.13;
      for(var i=0;i<N;i++){
        var pt=P[i], c=pt.cell, g=pt.glb;
        var t=easeInOut(clamp((m1-pt.delay)/0.40,0,1));
        var ix=imgCx+c.u*imgW, iy=imgCy+c.v*imgH;
        var gx,gy,depth;
        if(COVER){ var lh=pt.lh; gx=cx+(lh?lh.dx:0); gy=cy+(lh?lh.dy:0); depth=1; }   // destino: faro (se forma como el mapamundi)
        else { var xr=g.x*cos+g.z*sin, zr=-g.x*sin+g.z*cos, yr=g.y; gx=cx+xr*R; gy=cy-yr*R; depth=(zr+1)/2; }
        var it=1-t;
        var midx=(ix+gx)*0.5, midy=(iy+gy)*0.5;
        var cpx=midx + wdx*WIND*pt.wind + pxx*LAT*pt.lat;
        var cpy=midy + wdy*WIND*pt.wind + pyy*LAT*pt.lat;
        var X=it*it*ix + 2*it*t*cpx + t*t*gx;
        var Y=it*it*iy + 2*it*t*cpy + t*t*gy;
        var fade=it;
        var sway=Math.sin(t*Math.PI*pt.swayF + pt.phase)*SWAY*pt.swayA*fade;
        X+=pxx*sway; Y+=pyy*sway;
        Y+=Math.sin(t*Math.PI*2+pt.phase)*BOB*pt.bob*fade;
        var ct=clamp(t*1.25,0,1);
        var cr=(c.r+(11-c.r)*ct)|0, cg=(c.g+(14-c.g)*ct)|0, cb=(c.b+(18-c.b)*ct)|0;
        var side=lerp(imgPitch*1.05, lerp(2.4,4.0,depth)*0.55, t);
        var a=lerp(0.97, lerp(0.12,0.92,depth), t);
        if(a<=0.02||side<=0.3) continue;
        ctx.fillStyle="rgba("+cr+","+cg+","+cb+","+a+")";
        var hh=side*0.5; ctx.fillRect(X-hh,Y-hh,side,side);
      }
    }

    // ---- Marcadores amarillos sobre el mapamundi ----
    if(!COVER && cellsReady && pp<0.39){
      var mk = remap(pp,0.20,0.24) * (1 - remap(pp,0.34,0.38));
      if(mk>0){
        var ms=Math.sin(angle1), mc=Math.cos(angle1);
        var tnow=(typeof performance!=="undefined"?performance.now():Date.now())/1000;
        for(var k=0;k<MARKERS.length;k++){
          var mm=MARKERS[k];
          var mxr=mm.x*mc+mm.z*ms, mzr=-mm.x*ms+mm.z*mc;
          if(mzr<=0.05) continue;
          var mgx=cx+mxr*R, mgy=cy-mm.y*R, mdepth=(mzr+1)/2;
          var pulse=1+0.45*Math.sin(tnow*mm.speed + mm.phase);
          var rad=mm.size*R*(0.7+0.3*mdepth)*pulse;
          var al=mk*(0.55+0.45*mdepth);
          ctx.beginPath(); ctx.fillStyle="rgba(255,212,0,"+(al*0.22)+")";
          ctx.arc(mgx,mgy,rad*2.2,0,TWO_PI); ctx.fill();
          ctx.beginPath(); ctx.fillStyle="rgba(255,212,0,"+al+")";
          ctx.arc(mgx,mgy,rad,0,TWO_PI); ctx.fill();
        }
      }
    }

    // ---- ESCENA 1.5: mapamundi -> mapa de Espana (mapa real con comunidades) ----
    if(!COVER && cellsReady && spainPhase){
      var aF1=TWO_PI*(TURNS + 0.8*0.37);          // orientacion del globo congelada al iniciar el morph
      var s1=Math.sin(aF1), c1=Math.cos(aF1);
      for(var i=0;i<N;i++){
        var pt=P[i], g=pt.glb, sp=pt.spain;
        var t=easeInOut(clamp((mS-pt.delay)/0.40,0,1));
        var xr1=g.x*c1+g.z*s1, zr1=-g.x*s1+g.z*c1, depth=(zr1+1)/2;
        var sx=cx+xr1*R, sy=cy-g.y*R;                    // origen: mapamundi
        var dx=spainCx+sp.u*spnW, dy=spainCy+sp.v*spnH;  // destino: pixel del mapa de Espana
        var X=lerp(sx,dx,t), Y=lerp(sy,dy,t);
        var cr=lerp(11,sp.r,t)|0, cg=lerp(14,sp.g,t)|0, cb=lerp(18,sp.b,t)|0;
        var side=lerp(lerp(2.4,4.0,depth)*0.55, spainPitch*1.05, t);
        var a=lerp(lerp(0.12,0.92,depth), 0.95, t);
        if(a<=0.02||side<=0.3) continue;
        ctx.fillStyle="rgba("+cr+","+cg+","+cb+","+a+")";
        var hh=side*0.5; ctx.fillRect(X-hh,Y-hh,side,side);
      }
      if(spainReady){ var faS=remap(pp,0.46,0.50);   // funde el MAPA REAL nitido por encima
        if(faS>0){ ctx.globalAlpha=faS; ctx.drawImage(spainImg,0,0,SPAIN.fw,SPAIN.fh, spainCx-spnW/2,spainCy-spnH/2,spnW,spnH); ctx.globalAlpha=1; } }
    }

    // ---- ESCENA 1.75: mapa de Espana -> 9 CARAS (composicion) ----
    if(!COVER && cellsReady && compPhase){
      if(spainReady){ var faSo0=1-remap(pp,0.78,0.82);   // retira el mapa de Espana
        if(faSo0>0){ ctx.globalAlpha=faSo0; ctx.drawImage(spainImg,0,0,SPAIN.fw,SPAIN.fh, spainCx-spnW/2,spainCy-spnH/2,spnW,spnH); ctx.globalAlpha=1; } }
      for(var i=0;i<N;i++){
        var pt=P[i], sp=pt.spain, co=pt.comp;
        var t=easeInOut(clamp((mComp-pt.delay)/0.40,0,1));
        var sx=spainCx+sp.u*spnW, sy=spainCy+sp.v*spnH;
        var dcx=compCx+co.u*compW, dcy=compCy+co.v*compH;
        var X=lerp(sx,dcx,t), Y=lerp(sy,dcy,t);
        var cr=lerp(sp.r,co.r,t)|0, cg=lerp(sp.g,co.g,t)|0, cb=lerp(sp.b,co.b,t)|0;
        var side=lerp(spainPitch*1.05, compPitch*1.05, t);
        var a=lerp(0.95, 0.9, t);
        if(a<=0.02||side<=0.3) continue;
        ctx.fillStyle="rgba("+cr+","+cg+","+cb+","+a+")";
        var hh=side*0.5; ctx.fillRect(X-hh,Y-hh,side,side);
      }
      drawComp(remap(pp,0.82,0.85));   // funde la composicion (borrosa + revelado por hover)
    }

    // ---- ESCENA 2: 9 caras -> video 2 ----
    if(!COVER && cellsReady && v2Phase){
      if(CARAS){ drawComp(1-remap(pp,0.91,0.94)); }                       // las 9 caras se retiran
      else if(spainReady){ var faSo=1-remap(pp,0.86,0.90);                 // el mapa de Espana se retira
        if(faSo>0){ ctx.globalAlpha=faSo; ctx.drawImage(spainImg,0,0,SPAIN.fw,SPAIN.fh, spainCx-spnW/2,spainCy-spnH/2,spnW,spnH); ctx.globalAlpha=1; } }
      for(var i=0;i<N;i++){
        var pt=P[i], so=CARAS?pt.comp:pt.spain, c2=pt.cell2;
        var t=easeInOut(clamp((m2-pt.delay)/0.40,0,1));
        var sx=CARAS?(compCx+so.u*compW):(spainCx+so.u*spnW), sy=CARAS?(compCy+so.v*compH):(spainCy+so.v*spnH);
        var dx2=img2Cx+c2.u*img2W, dy2=img2Cy+c2.v*img2H;  // destino: pixel del video 2
        var X=lerp(sx,dx2,t), Y=lerp(sy,dy2,t);
        var cr=lerp(so.r,c2.r,t)|0, cg=lerp(so.g,c2.g,t)|0, cb=lerp(so.b,c2.b,t)|0;
        var side=lerp((CARAS?compPitch:spainPitch)*1.05, img2Pitch*1.05, t);
        var a=lerp(0.93, 0.97, t);
        if(a<=0.02||side<=0.3) continue;
        ctx.fillStyle="rgba("+cr+","+cg+","+cb+","+a+")";
        var hh=side*0.5; ctx.fillRect(X-hh,Y-hh,side,side);
      }
      if(sprite2Ready){
        var fa2=CARAS?remap(pp,0.955,0.975):remap(pp,0.92,0.95);
        if(fa2>0){
          var pf=clamp(Math.round((CARAS?remap(pp,0.975,1.0):remap(pp,0.95,1.0))*(V2.frames-1)),0,V2.frames-1);
          var f2=pf, c2col=f2%V2.cols, c2row=(f2/V2.cols)|0;
          ctx.globalAlpha=fa2;
          ctx.drawImage(sprite2, c2col*V2.fw,c2row*V2.fh,V2.fw,V2.fh, img2Cx-img2W/2,img2Cy-img2H/2,img2W,img2H);
          ctx.globalAlpha=1;
          var ix2=img2Cx-img2W/2, ix2r=img2Cx+img2W/2, yb2=img2Cy+img2H/2;
          var b2B=img2H*0.16, b2R=img2W*0.07, b2L=img2W*0.07;
          ctx.globalCompositeOperation="destination-out";
          var g2B=ctx.createLinearGradient(0,yb2-b2B,0,yb2);
          g2B.addColorStop(0,"rgba(0,0,0,0)"); g2B.addColorStop(1,"rgba(0,0,0,"+fa2+")");
          ctx.fillStyle=g2B; ctx.fillRect(0,yb2-b2B,W,b2B);
          var g2R=ctx.createLinearGradient(ix2r-b2R,0,ix2r,0);
          g2R.addColorStop(0,"rgba(0,0,0,0)"); g2R.addColorStop(1,"rgba(0,0,0,"+fa2+")");
          ctx.fillStyle=g2R; ctx.fillRect(ix2r-b2R,0,b2R,H);
          var g2L=ctx.createLinearGradient(ix2,0,ix2+b2L,0);
          g2L.addColorStop(0,"rgba(0,0,0,"+fa2+")"); g2L.addColorStop(1,"rgba(0,0,0,0)");
          ctx.fillStyle=g2L; ctx.fillRect(ix2,0,b2L,H);
          ctx.globalCompositeOperation="source-over";
        }
      }
    }
    // ---- Orbes amarillos pulsantes sobre comunidades del mapa de Espana ----
    if(!COVER && cellsReady && pp>=0.48 && pp<(esFrag+0.04)){
      var mv=remap(pp,0.48,0.52)*(1-remap(pp,esFrag,esFrag+0.04));
      if(mv>0){
        var tno=(typeof performance!=="undefined"?performance.now():Date.now())/1000;
        for(var q=0;q<SPAIN_MARKERS.length;q++){
          var sm=SPAIN_MARKERS[q];
          var ox=spainCx+sm.u*spnW, oy=spainCy+sm.v*spnH;
          var pul=1+0.45*Math.sin(tno*sm.speed+sm.phase);
          var orad=sm.size*spnW*pul, oa=mv;
          ctx.beginPath(); ctx.fillStyle="rgba(255,212,0,"+(oa*0.22)+")"; ctx.arc(ox,oy,orad*2.2,0,TWO_PI); ctx.fill();
          ctx.beginPath(); ctx.fillStyle="rgba(255,212,0,"+oa+")"; ctx.arc(ox,oy,orad,0,TWO_PI); ctx.fill();
        }
      }
    }

    // ---- Orbe de Madrid (DOM, por encima del copy) que crece hasta llenar la pantalla y encoge ----
    if(orbCoverEl){
      if(cellsReady && coverT>0.001 && pp>=0.55 && pp<0.86){
        var mad=SPAIN_MARKERS[1];
        var madx=spainCx+mad.u*spnW, mady=spainCy+mad.v*spnH, madBase=mad.size*spnW;
        var coverRad=Math.max(Math.hypot(madx,mady),Math.hypot(W-madx,mady),Math.hypot(madx,H-mady),Math.hypot(W-madx,H-mady))+6;
        var orbR=lerp(madBase, coverRad, easeInOut(coverT));
        orbCoverEl.style.display="block";
        orbCoverEl.style.width=orbCoverEl.style.height=(orbR*2)+"px";
        orbCoverEl.style.left=(madx-orbR)+"px";
        orbCoverEl.style.top=(mady-orbR)+"px";
      } else { orbCoverEl.style.display="none"; }
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
